extern "C" void render(float* out, int n, double* pts, int m, double scale){
 std::fill(out,out+n*n,0.f);
 for(int k=0;k<m;k++){
  double x=pts[k*4]*scale,y=pts[k*4+1]*scale,w=pts[k*4+2]*scale,th=pts[k*4+3];
  if(w<.05)continue;
  double d=(1.38+1.075*((pts[k*4+2]*.22185986964255727+.3)/1.187))/.22185986964255727*scale;
  double ex=cos(th),ey=sin(th),nx=-ey,ny=ex;
  int x0=std::max(0,(int)floor(std::min(x-w/2*nx,x+w/2*nx)-std::max(0.,d*ex)-2));
  int x1=std::min(n-1,(int)ceil(std::max(x-w/2*nx,x+w/2*nx)+std::max(0.,-d*ex)+2));
  int y0=std::max(0,(int)floor(std::min(y-w/2*ny,y+w/2*ny)-std::max(0.,d*ey)-2));
  int y1=std::min(n-1,(int)ceil(std::max(y-w/2*ny,y+w/2*ny)+std::max(0.,-d*ey)+2));
  for(int j=y0;j<=y1;j++)for(int i=x0;i<=x1;i++){
   double qx=i-x,qy=j-y,s=-(qx*ex+qy*ey),t=qx*nx+qy*ny;
   double fp=d*(1.-4*t*t/(w*w))-s;
   double g=sqrt(1.+pow(8*d*t/(w*w),2));
   float a=std::max(0.,std::min(1.,std::min(s,fp/g)+.5));
   out[j*n+i]=std::max(out[j*n+i],a);
  }
 }
